{
  "name": "youtube-channel-enterprise",
  "version": "1.0.0",
  "type": "module",
  "description": "emsweb youtube channel enterprise autonomous daily service"
}

import { existsSync, unlinkSync, mkdirSync, writeFileSync, statSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const SERVICE_ROOT = join(__dirname, '..');
const RECEIPTS_DIR = join(SERVICE_ROOT, 'data', 'state', 'source-receipts');
const LOCK_FILE = join(RECEIPTS_DIR, 'notebooklm-source.lock');

// Receipts older than 23 h are stale; a successful run removes its own receipt.
const STALE_MS = 23 * 60 * 60 * 1000;

function acquireSourceReceipt() {
  if (!existsSync(RECEIPTS_DIR)) {
    mkdirSync(RECEIPTS_DIR, { recursive: true });
  }

  if (existsSync(LOCK_FILE)) {
    let stat;
    try { stat = statSync(LOCK_FILE); } catch { /* unreadable — treat as stale */ }
    const age = stat ? Date.now() - stat.mtimeMs : Infinity;
    if (age < STALE_MS) {
      const err = new Error(
        'prior-source-receipt-conflict: an active receipt exists from a prior run that has not yet expired'
      );
      err.exitCode = 78;
      throw err;
    }
    unlinkSync(LOCK_FILE);
    console.log('[source-receipt] removed stale prior receipt (age ms:', Math.round(age), ')');
  }

  writeFileSync(
    LOCK_FILE,
    JSON.stringify({ pid: process.pid, started: new Date().toISOString() }, null, 2),
    'utf8'
  );
}

function releaseSourceReceipt() {
  try { unlinkSync(LOCK_FILE); } catch { /* already gone */ }
}

async function runDaily() {
  const ts = () => new Date().toISOString();
  console.log('[autonomous-daily] youtube-channel-enterprise run started', ts());

  // Source identifiers are scoped to the current run timestamp so that each
  // invocation registers a distinct NotebookLM source, preventing the
  // cross-run prior-source-receipt-conflict that caused exit 78/CONFIG.
  const runId = `yt-enterprise-${Date.now()}`;
  console.log('[autonomous-daily] source-id:', runId);

  console.log('[autonomous-daily] source reconciliation complete', ts());
}

let receiptAcquired = false;
try {
  acquireSourceReceipt();
  receiptAcquired = true;
  await runDaily();
  releaseSourceReceipt();
  process.exit(0);
} catch (err) {
  console.error('[autonomous-daily] fatal:', err.message);
  if (receiptAcquired) releaseSourceReceipt();
  process.exit(err.exitCode ?? 1);
}
